-- Content sync: the catalog from src/content/dictionary.ts
-- Counts: 100 daily questions, 50 challenges, 25 journal prompts, 14 story starters.

-- 1. Old challenge rows (ch-001 to ch-010) are retired, not deleted, so past history still resolves.
update public.content_items set status = 'retired', updated_at = now()
where type = 'challenge' and ref like 'ch-%';

-- 2. Daily questions
on conflict (ref) do update set
  type = excluded.type,
  body = excluded.body,
  depth = excluded.depth,
  tags = excluded.tags,
  options = excluded.options,
  spicy = excluded.spicy,
  status = 'published',
  updated_at = now();

-- 3. Challenges. The remote variant is used automatically for long-distance couples.
on conflict (ref) do update set
  type = excluded.type,
  body = excluded.body,
  depth = excluded.depth,
  tags = excluded.tags,
  options = excluded.options,
  spicy = excluded.spicy,
  status = 'published',
  updated_at = now();

-- 4. Journal prompts
on conflict (ref) do update set
  type = excluded.type,
  body = excluded.body,
  depth = excluded.depth,
  tags = excluded.tags,
  options = excluded.options,
  spicy = excluded.spicy,
  status = 'published',
  updated_at = now();

-- 5. Story starters. "our-future" is stored as "our_future" to match the app.
on conflict (ref) do update set
  type = excluded.type,
  body = excluded.body,
  depth = excluded.depth,
  tags = excluded.tags,
  options = excluded.options,
  spicy = excluded.spicy,
  status = 'published',
  updated_at = now();
